    r'state': PropertySchema(
      id: 3,
      name: r'state',
      type: IsarType.string,
    ),
    r'street': PropertySchema(
      id: 4,
      name: r'street',
      type: IsarType.string,
    ),
    r'zipCode': PropertySchema(
      id: 5,
      name: r'zipCode',
      type: IsarType.string,
    )
  },
  estimateSize: _addressEstimateSize,
  serialize: _addressSerialize,
  deserialize: _addressDeserialize,
  deserializeProp: _addressDeserializeProp,
);

int _addressEstimateSize(
  Address object,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  var bytesCount = offsets.last;
  bytesCount += 3 + object.city.length * 3;
  bytesCount += 3 + object.neighborhood.length * 3;
  bytesCount += 3 + object.number.length * 3;
  bytesCount += 3 + object.state.length * 3;
  bytesCount += 3 + object.street.length * 3;
  bytesCount += 3 + object.zipCode.length * 3;
  return bytesCount;
}

void _addressSerialize(
  Address object,
  IsarWriter writer,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  writer.writeString(offsets[0], object.city);
  writer.writeString(offsets[1], object.neighborhood);
  writer.writeString(offsets[2], object.number);
  writer.writeString(offsets[3], object.state);
  writer.writeString(offsets[4], object.street);
  writer.writeString(offsets[5], object.zipCode);
}

Address _addressDeserialize(
  Id id,
  IsarReader reader,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  final object = Address();
  object.city = reader.readString(offsets[0]);
  object.neighborhood = reader.readString(offsets[1]);
  object.number = reader.readString(offsets[2]);
  object.state = reader.readString(offsets[3]);
  object.street = reader.readString(offsets[4]);
  object.zipCode = reader.readString(offsets[5]);
  return object;
}

P _addressDeserializeProp<P>(
  IsarReader reader,
  int propertyId,
  int offset,
  Map<Type, List<int>> allOffsets,
) {
  switch (propertyId) {
    case 0:
      return (reader.readString(offset)) as P;
    case 1:
      return (reader.readString(offset)) as P;
    case 2:
      return (reader.readString(offset)) as P;
    case 3:
      return (reader.readString(offset)) as P;
    case 4:
      return (reader.readString(offset)) as P;
    case 5:
      return (reader.readString(offset)) as P;
    default:
      throw IsarError('Unknown property with id $propertyId');
  }
}

